namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int MaximumRatePoints = 10;

    public static int PayableTotalCents(LoyaltyTier tier, int subtotalCents)
    {
        var ratePoints = Math.Min(BaseRatePoints(tier) + OrderSizeBonusPoints(subtotalCents), MaximumRatePoints);
        var discountCents = (int)((long)subtotalCents * ratePoints / 100);

        return subtotalCents - discountCents;
    }

    private static int BaseRatePoints(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 7,
        LoyaltyTier.Gold => 9,
    };

    private static int OrderSizeBonusPoints(int subtotalCents) => subtotalCents switch
    {
        < 5000 => 0,
        < 20000 => 1,
        _ => 3,
    };
}
EOF
cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'EOF'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    public int For(LoyaltyTier tier, int subtotalCents)
    {
        return LoyaltyDiscountPolicy.PayableTotalCents(tier, subtotalCents);
    }
}
EOF
